class TMP117_Simulator(BaseVirtualSensor):
    REG_WIDTH = 16  # 本基准目标器件寄存器宽度（16 位为主）

    def __init__(self):
        super().__init__()
        # Initialize all registers to their reset values
        self.regs = {
            0x00: 0x8000,  # TEMP
            0x01: 0x0220,  # CONFIG
            0x02: 0x6000,  # THIGH
            0x03: 0x8000,  # TLOW
            0x04: 0x0000,  # EEPROM_UL
            0x05: 0x0000,  # EEPROM1
            0x06: 0x0000,  # EEPROM2
            0x07: 0x0000,  # TEMP_OFFSET
            0x08: 0x0000,  # EEPROM3
            0x0F: 0x0117,  # DEVICE_ID
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        if addr not in self.regs:
            raise ValueError(f"Register {addr} does not exist.")
        value = self.regs[addr]
        if nbytes == 1:
            return value & 0xFF  # Return only the least significant byte
        return value

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Register {addr} does not exist.")

        if nbytes == 1:
            # Update only the least significant byte of the register
            self.regs[addr] &= ~(0xFF << (8 - self.REG_WIDTH))
            self.regs[addr] |= (data & 0xFF) << (8 - self.REG_WIDTH)
        else:
            # Update the entire register
            self.regs[addr] = data

        # Apply read_as constraints
        for field in self.get_fields(addr):
            if field['read_as'] is not None:
                self.regs[addr] = field['read_as']

    def get_fields(self, addr: int) -> list:
        reg_desc = next((reg for reg in self.device['registers'] if reg['addr'] == hex(addr)), None)
        if reg_desc is None:
            raise ValueError(f"Register {addr} does not exist.")
        return reg_desc['fields']

